package com.bautruc.ecommerce.commerce.application;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;class CheckoutRequestHasherTest{@Test void isDeterministicAndSensitiveToLogicalFields(){CheckoutRequestHasher h=new CheckoutRequestHasher();var a=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null);assertThat(h.hash(a)).hasSize(64).isEqualTo(h.hash(a));assertThat(h.hash(a)).isNotEqualTo(h.hash(new NormalizedCheckoutRequest("A","09000000","a@example.com","Y",null)));}@Test void buyNowProductAndQuantityArePartOfIdempotencyHash(){CheckoutRequestHasher h=new CheckoutRequestHasher();var cart=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null);var one=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null,10L,1);var two=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null,10L,2);var other=new NormalizedCheckoutRequest("A","09000000","a@example.com","X",null,11L,1);assertThat(h.hash(cart)).isNotEqualTo(h.hash(one));assertThat(h.hash(one)).isNotEqualTo(h.hash(two)).isNotEqualTo(h.hash(other));}}
